function el(tag,classes,text){const node=document.createElement(tag);if(classes)node.className=classes;if(text!==undefined)node.textContent=text;return node;}
function glyph(name){const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('aria-hidden','true');const p=document.createElementNS(svg.namespaceURI,'path');p.setAttribute('d',paths[name]||paths.monitor);svg.append(p);return svg;}
function button(text,action,{icon,classes='',title}={}){const b=el('button',classes);b.type='button';b.title=t(title||text);b.setAttribute('aria-label',t(title||text));if(icon)b.append(glyph(icon));if(text){if(icon)b.append(document.createTextNode(' '));b.append(document.createTextNode(t(text)));}b.addEventListener('click',event=>{event.stopPropagation();Promise.resolve(action(event)).catch(error=>toast(error.message));});return b;}
async function api(route,body){const res=await fetch('/api/'+route,{method:body===undefined?'GET':'POST',headers:{'x-cmcp-token':token,...(body===undefined?{}:{'content-type':'application/json'})},...(body===undefined?{}:{body:JSON.stringify(body)})});const value=await res.json();if(!res.ok)throw Error(data.preferences.language==='en'?(english[value.error]||t('操作未完成，请检查连接状态后重试。')):value.error);return value;}
window.cmcpNativeReply=(id,value,error)=>{const pending=nativePending.get(id);if(!pending)return;nativePending.delete(id);clearTimeout(pending.timer);error?pending.reject(Error(error)):pending.resolve(value);};
const nativePending=new Map();
function native(action,payload={}){if(!window.webkit?.messageHandlers?.cmcp)return Promise.reject(Error('Native host unavailable'));return new Promise((resolve,reject)=>{const id=++nativeSequence;const timer=['update','install-update'].includes(action)?null:setTimeout(()=>{nativePending.delete(id);reject(Error('Native action timed out'));},180000);nativePending.set(id,{resolve,reject,timer});window.webkit.messageHandlers.cmcp.postMessage({id,action,payload});});}
function toast(message){notice.textContent=t(message);notice.classList.add('visible');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>notice.classList.remove('visible'),5000);}
function theme(){const chosen=data.preferences.theme;document.documentElement.dataset.theme=chosen==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):chosen;document.documentElement.lang=data.preferences.language;}
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',theme);
function stateName(target){if(!target.enabled)return '已停止';return ({connected:'已连接',connecting:'连接中',unstable:'正在恢复',recovering:'正在恢复',configuring:'正在配置 Claude','config-error':'连接异常','waiting-login':'等待网页登录',offline:'连接中',password:'需要更新密码',locked:'连接异常',expired:'连接异常',replaced:'连接已被接管',error:'连接异常'})[target.state]||'连接中';}
function icon(dataURL,large=false){const box=el('div','project-icon'+(large?' editor-icon':''));if(dataURL){const img=el('img');img.src=dataURL;img.alt='';box.append(img);}else box.append(glyph('monitor'));return box;}
function toolbar(title){const h=el('header');if(page!=='home')h.append(button('',()=>{editor=null;go('home');},{icon:'back',classes:'icon-button',title:'返回'}));h.append(el(page==='home'?'h1':'h2','',page==='home'?'CMCP':t(title)));if(page==='home'){const gear=button('',()=>go('settings'),{icon:'settings',classes:'icon-button soft gear',title:'设置'});gear.removeAttribute('title');gear.append(dot());const right=el('div','right');const add=button('添加设备',()=>openEditor(),{icon:'plus',classes:'primary'});add.removeAttribute('title');add.lastChild.replaceWith(el('span','add-device-label',t('添加设备')));right.append(add);const ring=el('div','update-ring');ring.hidden=true;ring.tabIndex=0;ring.setAttribute('role','progressbar');ring.setAttribute('aria-valuemin','0');ring.setAttribute('aria-valuemax','100');ring.dataset.focusKey='update:ring';ring.innerHTML='<svg viewBox="0 0 32 32" aria-hidden="true"><circle class="ring-track" cx="16" cy="16" r="12"/><circle class="ring-fill" cx="16" cy="16" r="12" pathLength="100"/><text class="ring-error" x="16" y="21">!</text></svg>';h.append(gear,ring,right);for(const [index,node]of [...h.querySelectorAll('button')].entries())node.dataset.focusKey='header:'+index;}return h;}
function dot(){const node=el('span','dot');node.hidden=true;node.setAttribute('aria-hidden','true');return node;}
let updateActive=false,updatePolling=false,updateChecking=false,updateUI=null;
Object.assign(english,{'正在检查当前安装':'Checking the current installation','正在获取更新信息':'Getting update information','正在下载更新':'Downloading update','正在校验下载文件':'Verifying the download','正在解压更新':'Extracting update','正在校验安装包':'Verifying the package','更新已准备，正在重新启动…':'Update verified. Restarting…','更新未完成':'Update did not complete','请稍候；验证完成前不会替换当前安装。':'Please wait. The current installation stays in place until verification succeeds.','下载连接失败，请检查网络或代理后点击更新重试。':'Download failed. Check the network or proxy, then click Update to retry.','下载超时，请检查网络后点击更新重试。':'The download timed out. Check the network, then click Update to retry.','下载文件校验失败，当前安装未替换，请点击更新重新下载。':'Download verification failed. The installation is unchanged. Click Update to download again.','没有找到有效的 Mac 更新包，请前往发布页检查。':'No valid Mac update package was found. Check the release page.','更新准备失败，当前安装未替换；可重试或在设置中打开日志文件夹。':'Update preparation failed. The installation is unchanged. Retry or open the log folder in Settings.'});
