Object.assign(english,{'浏览器':'Browser','系统默认浏览器':'System default browser','打开共享网页时使用的浏览器。这里只列出这台 Mac 已安装的浏览器。':'The browser that opens shared web pages. Only browsers installed on this Mac are listed.','断开连接后关闭网页':'Close the web page on disconnect','网页在 CMCP 单独打开的 {0} 窗口中显示，断开连接时关闭这个窗口。这个窗口的登录状态与平时的浏览器分开，第一次需要登录一次。':'The page opens in a separate {0} window from CMCP, which closes on disconnect. Its sign-in is kept apart from your usual browser, so you sign in there once.','Safari 打开的网页 CMCP 无法关闭。请在上面选择 Chrome、Edge 或 Firefox。':'CMCP cannot close a page in Safari. Choose Chrome, Edge or Firefox above.','系统默认浏览器打开的网页 CMCP 无法关闭。请先在上面选择具体的浏览器。':'CMCP cannot close a page in the system default browser. Choose a specific browser above first.','SSH 登录时使用的终端。这里只列出这台 Mac 已安装的终端。':'The terminal used for SSH. Only terminals installed on this Mac are listed.','断开连接后关闭终端':'Close the terminal on disconnect','断开连接时结束这台设备的 SSH 会话，终端窗口随之关闭。只对之后打开的终端生效。':'Disconnecting ends this device\'s SSH session and closes its terminal window. Applies to terminals opened from now on.','SSH 通道已停止，终端窗口已关闭。':'SSH channel stopped and terminal windows closed.'});
Object.assign(english,{'外观':'Appearance','主题':'Theme','窗口':'Window','快捷方式':'Shortcuts','创建':'Create','打开':'Open','发布页':'Releases','本机文件夹':'Local folders','立即更新':'Update now','发现新版本':'New version','当前版本':'Current version','更新时会短暂断开连接。':'Connections drop briefly during the update.','查看每个版本的更新内容。':'See what changed in each version.','关闭时最小化到菜单栏':'Minimize to menu bar on close','开启时窗口隐藏到菜单栏，已连接的设备保持连接；关闭后，关闭窗口会退出并断开全部连接。':'When on, the window hides to the menu bar and connected devices stay connected. When off, closing the window exits and disconnects everything.','登录 Mac 后在菜单栏运行，不打开窗口；可以从菜单栏图标打开主界面。':'After you sign in to this Mac, CMCP runs in the menu bar without opening its window. Open it from the menu bar icon.','在桌面创建 CMCP 的替身。':'Create an alias to CMCP on the desktop.','快捷方式已创建。':'Desktop shortcut created.','设置 · 有可用更新':'Settings · Update available','正在检查…':'Checking…','检查失败，请重试':'Check failed. Try again.','断开全部连接，尽量移除云电脑上的 Claude 配置，并删除本机的程序、设置和保存的密码。':'Disconnects everything, removes the Claude configuration from cloud PCs where it can, and deletes the app, its settings and saved passwords from this Mac.'});
function renderUpdateProgress(){
  const u=data.updates||{};ringState=updateRing(u,ringState);
  let banner=root.querySelector('.update-banner');
  const stages={installed:'正在检查当前安装',release:'正在获取更新信息',download:'正在下载更新',checksum:'正在获取校验信息',extract:'正在解压更新',verify:'正在校验安装包',ready:'更新已下载并校验，等待安装确认',restart:'更新已准备，正在重新启动…'};
  const failed=u.state==='failed',title=t(failed?'更新未完成':stages[u.phase]||'正在获取更新信息');
  let detail=t('请稍候；验证完成前不会替换当前安装。'),percent=null;
  if(failed)detail=t(({network:'下载连接失败，请检查网络或代理后点击更新重试。',timeout:'下载超时，请检查网络后点击更新重试。',checksum:'下载文件校验失败，当前安装未替换，请点击更新重新下载。',release:'没有找到有效的 Mac 更新包，请前往发布页检查。'})[u.code]||'更新准备失败，当前安装未替换；可重试或在设置中打开日志文件夹。');
  else if(u.state==='ready'){percent=100;detail=t('当前版本仍在运行；点击“安装更新”后确认安装。');}
  else if(Number.isFinite(u.received)&&u.received>=0&&Number.isFinite(u.total)&&u.total>0&&u.received<=u.total){percent=Math.floor(u.received/u.total*100);detail=u.unit==='files'?`${u.received} / ${u.total} ${t('个文件')} · ${percent}%`:`${(u.received/1048576).toFixed(1)} / ${(u.total/1048576).toFixed(1)} MB · ${percent}%`;}
  const ring=root.querySelector('.update-ring');if(ring){ring.hidden=!ringState.visible;if(ringState.visible){ring.classList.toggle('failed',failed);ring.querySelector('.ring-fill').style.strokeDashoffset=String(100-ringState.percent);ring.setAttribute('aria-label',title);ring.setAttribute('aria-valuenow',String(ringState.percent));const hint=title+'\n'+(failed?'':t('总体进度（估算）')+'：'+ringState.percent+'%\n')+detail;ring.setAttribute('aria-valuetext',hint);if(ring.dataset.tooltip!==hint)ring.dataset.tooltip=hint;}}
  if(page!=='about'){banner?.remove();return;}
  if(!banner){banner=el('section','update-banner');banner.setAttribute('aria-live','polite');}
  const slot=root.querySelector('.update-slot');if(slot){if(banner.parentNode!==slot)slot.append(banner);}else{const main=root.querySelector('main');if(banner.parentNode!==main.parentNode)main.parentNode.insertBefore(banner,main);}
  banner.hidden=!ringState.visible;if(banner.hidden)return;
  banner.classList.toggle('failed',failed);const meter=el('progress');meter.max=100;if(percent!==null)meter.value=percent;
  banner.replaceChildren(el('strong','',title),el('p','muted',detail));if(!failed)banner.append(meter);
}
function syncUpdates(){
  const view=updateView(data.updates,updateChecking,updateActive);
  for(const node of root.querySelectorAll('.dot'))node.hidden=!view.offered;
  const gear=root.querySelector('.gear');if(gear){const label=t(view.offered?'设置 · 有可用更新':'设置');gear.removeAttribute('title');delete gear.dataset.tooltip;gear.setAttribute('aria-label',label);}
  if(updateUI){const {run,check,checkDetail,title,detail}=updateUI,label=t(view.button);title.textContent=view.offered?`${t('发现新版本')} ${view.version||''}`.trim():'CMCP '+data.version;detail.textContent=view.offered?`${t('当前版本')} ${data.version} · ${t(view.prepared?'更新已下载并校验，可稍后安装。':'下载并校验后，由你确认是否安装。')}`:[String(data.platform||'').replace('macos-','macOS '),view.status&&t(view.status)].filter(Boolean).join(' · ');run.textContent=label;run.title=label;run.setAttribute('aria-label',label);run.disabled=view.busy||!view.offered;const checkLabel=t(updateChecking?'正在检查…':'检查更新');check.textContent=checkLabel;check.title=checkLabel;check.setAttribute('aria-label',checkLabel);check.disabled=view.busy;checkDetail.textContent=t(view.status||'重新获取最新版本，包括已发现更新之后发布的版本。');}
  renderUpdateProgress();
}
// While an update runs the backend reports its old state until the download starts.
async function refreshUpdateProgress(){if(updatePolling)return;updatePolling=true;try{const value=await api('state');if(!updateActive||['updating','failed','ready'].includes(value.updates?.state)){data.updates=value.updates;syncUpdates();}}catch{}finally{updatePolling=false;}}
async function checkUpdates(){if(updateActive||updateChecking)return;updateChecking=true;syncUpdates();try{data.updates=await api('update/check',{});}catch{if(!updateView(data.updates).offered)data.updates={state:'error',version:null};}finally{updateChecking=false;syncUpdates();}}
async function installUpdate(){if(updateActive||updateChecking)return;const version=data.updates?.version||null,prepared=data.updates?.state==='ready';updateActive=true;if(!prepared)data.updates={state:'updating',phase:'release',version};syncUpdates();const timer=setInterval(refreshUpdateProgress,500);try{const value=await native(prepared?'install-update':'update');if(value?.prepared)data.updates={state:'ready',phase:'ready',version:value.version,received:1,total:1};}catch{await refreshUpdateProgress();if(data.updates?.state!=='failed')data.updates={state:'failed',code:'prepare',version};}finally{clearInterval(timer);updateActive=false;syncUpdates();}}
// `at` only says when a state was last reported, and nothing on the page shows it.
function listView(){return JSON.stringify([data.targets,data.preferences.language],(key,value)=>key==='at'?undefined:value);}
// Rebuilding only on a real change keeps the 2 s refresh from disturbing focus, tooltips or a press in progress.
function applyState(next){const before=JSON.stringify(data.updates);data=updateActive?{...next,updates:data.updates}:next;theme();if(page==='home'&&!dragId&&!reveal.active()&&listView()!==renderedView)render();else if(JSON.stringify(data.updates)!==before)syncUpdates();}
async function refresh(){try{applyState(await api('state'));}catch(error){if(!token)return;toast(error.message);}}
function progress(target){if(data.preferences.language!=='en'&&target.message)return target.message;return t(target.state==='connected'?'已连接，可以使用本机工具。':target.state==='waiting-login'?'请在打开的共享网页中完成登录。':!target.enabled?'已停止连接。':'正在等待连接恢复。');}
async function connect(target){if(!target.url)return toast('还没有填写共享网页地址，请编辑设备后再连接。');if(busy.has(target.id)&&!target.enabled)return;busy.add(target.id);selected=target.id;render();const opening=[...root.querySelectorAll('.card')].find(node=>node.dataset.id===target.id);if(opening&&!expanded.has(target.id)){void opening.offsetHeight;setExpanded(opening,true);}try{if(target.enabled){await api('targets/stop',{id:target.id});}else{await api('targets/start',{id:target.id});await refresh();const value=await api('targets/open',{id:target.id});if(!value.opened)await native('open',{url:value.url});}}finally{busy.delete(target.id);await refresh();}}
