const settingTabs={settings:['通用','sliders'],connect:['连接','link'],about:['关于','info']},RELEASES='https://github.com/isAlexYoung/cmcp/releases';
function settingsHeading(head){const [title,name]=settingTabs[page];head.replaceChildren(glyph(name),el('h2','',t(title)));}
function settings(){const layout=el('div','settings-page'),side=el('aside','settings-side'),nav=el('nav','settings-nav'),body=el('div','settings-body'),head=el('header'),main=el('main');
  for(const [value,[label,name]]of Object.entries(settingTabs)){const option=button(label,()=>{if(page!==value)showTab(value,nav,head);},{icon:name});option.dataset.value=value;option.dataset.focusKey='nav:'+value;if(value==='about')option.append(dot());nav.append(option);}markChosen(nav,page);
  side.append(button('返回',()=>go('home'),{icon:'back'}),el('div','side-label',t('设置')),nav,el('div','side-version','CMCP v'+data.version));settingsHeading(head);main.append(settingsColumn());body.append(head,main);layout.append(side,body);root.replaceChildren(layout);}
// Only the content below the heading moves; the sidebar and keyboard focus stay put.
function showTab(next,nav,head){hideMenu();const direction=pageDirection(page,next);page=next;markChosen(nav,next);settingsHeading(head);const column=settingsColumn();root.querySelector('.settings-column').replaceWith(column);syncUpdates();window.scrollTo(0,0);turn(column,direction);}
function settingsColumn(){const column=el('div','settings-column');updateUI=null;
  const section=(title,...rows)=>{const s=el('section','settings-section'),card=el('div','set-card');card.append(...rows);s.append(el('h3','',t(title)),card);column.append(s);return s;};
  const row=(title,detail,control)=>{const node=el(control.type==='checkbox'?'label':'div','set-row'),text=el('span','row-text');text.append(el('span','row-title',title&&t(title)),el('span','row-detail',detail&&t(detail)));node.append(text,control);return node;};
  const toggle=(name,checked,save)=>{const box=el('input','switch');box.type='checkbox';box.setAttribute('role','switch');box.checked=checked;box.dataset.focusKey='switch:'+name;box.addEventListener('change',()=>save(box.checked).catch(error=>{box.checked=!box.checked;toast(error.message);}));return box;};
  const open=(title,action)=>button('打开',action,{classes:'soft',title});
  if(page==='settings'){
    const field=dropdown('界面语言',[['zh-CN','简体中文'],['en','English']],data.preferences.language,language=>saveSettings({language}));
    const theme=segments('主题',[['system','跟随系统','monitor'],['light','浅色','sun'],['dark','深色','moon']],data.preferences.theme,async(value,group)=>{markChosen(group,value);try{await saveSettings({theme:value});}catch(error){markChosen(group,data.preferences.theme);throw error;}});
    section('外观',row('界面语言','',field),row('主题','',theme));
    section('窗口',row('开机自启','登录 Mac 后在菜单栏运行，不打开窗口；可以从菜单栏图标打开主界面。',toggle('autoStart',data.preferences.autoStart,on=>saveSettings({autoStart:on}))),row('关闭时最小化到菜单栏','开启时窗口隐藏到菜单栏，已连接的设备保持连接；关闭后，关闭窗口会退出并断开全部连接。',toggle('closeAction',data.preferences.closeAction==='tray',on=>saveSettings({closeAction:on?'tray':'exit'}))));
    section('快捷方式',row('桌面快捷方式','在桌面创建 CMCP 的替身。',button('创建',async()=>{await native('shortcut');toast('快捷方式已创建。');},{classes:'soft',title:'桌面快捷方式'})));
  }else if(page==='connect'){
    // A page CMCP may close opens with a profile of its own; Safari and the system default cannot.
    const browsers=data.browsers||[],chosen=browsers.find(item=>item.id===data.preferences.browser),closable=['chrome','edge','firefox'].includes(chosen?.id);
    if(!iconsAsked){iconsAsked=true;native('icons',{ids:['default',...browsers.map(item=>item.id)]}).then(found=>{browserIcons={'':found.default,...Object.fromEntries(browsers.map(item=>[item.id,found[item.id]]))};if(page==='connect')root.querySelector('.settings-column')?.replaceWith(settingsColumn());}).catch(()=>{iconsAsked=false;});}
    const browser=dropdown('浏览器',[['',t('系统默认浏览器'),browserIcons['']],...browsers.map(item=>[item.id,item.label,browserIcons[item.id]])],chosen?.id||'',async value=>{await saveSettings({browser:value});root.querySelector('.settings-column')?.replaceWith(settingsColumn());});browser.classList.add('wide');
    const closeWeb=toggle('closeWeb',closable&&data.preferences.closeWeb===true,on=>saveSettings({closeWeb:on}));closeWeb.disabled=!closable;
    const webRow=row('断开连接后关闭网页',closable?t('网页在 CMCP 单独打开的 {0} 窗口中显示，断开连接时关闭这个窗口。这个窗口的登录状态与平时的浏览器分开，第一次需要登录一次。').replace('{0}',chosen.label):chosen?'Safari 打开的网页 CMCP 无法关闭。请在上面选择 Chrome、Edge 或 Firefox。':'系统默认浏览器打开的网页 CMCP 无法关闭。请先在上面选择具体的浏览器。',closeWeb);webRow.classList.toggle('off',!closable);
    section('共享网页',row('浏览器','打开共享网页时使用的浏览器。这里只列出这台 Mac 已安装的浏览器。',browser),webRow);
    const terminals=data.terminals||[],rows=[];
    if(terminals.length){const current=terminals.find(item=>item.id===data.preferences.terminal)||terminals[0];rows.push(row('终端','SSH 登录时使用的终端。这里只列出这台 Mac 已安装的终端。',dropdown('终端',terminals.map(item=>[item.id,item.label]),current.id,terminal=>saveSettings({terminal}))));}
    rows.push(row('断开连接后关闭终端','断开连接时结束这台设备的 SSH 会话，终端窗口随之关闭。只对之后打开的终端生效。',toggle('closeTerminal',data.preferences.closeTerminal===true,on=>saveSettings({closeTerminal:on}))));
    section('SSH',...rows);
  }else{
    const run=button('下载更新',installUpdate,{classes:'primary'});run.dataset.focusKey='update:run';const status=row('','',run);
    const check=button('检查更新',checkUpdates);check.dataset.focusKey='update:check';const checkRow=row('检查更新','重新获取最新版本，包括已发现更新之后发布的版本。',check);
    updateUI={run,check,checkDetail:checkRow.querySelector('.row-detail'),title:status.querySelector('.row-title'),detail:status.querySelector('.row-detail')};
    const updates=section('更新',status,checkRow,row('发布页','查看每个版本的更新内容。',open('发布页',()=>native('open',{url:RELEASES}))));updates.querySelector('.set-card').before(el('div','update-slot'));
    section('本机文件夹',row('程序文件夹','',open('程序文件夹',()=>native('program'))),row('日志文件夹','',open('日志文件夹',()=>native('logs'))));
    section('卸载',row('卸载 CMCP','断开全部连接，尽量移除云电脑上的 Claude 配置，并删除本机的程序、设置和保存的密码。',button('卸载',uninstall,{classes:'danger-outline uninstall',title:'卸载 CMCP'})));
  }
  return column;}
function go(next){const direction=pageDirection(page,next);if(page==='home')homeScroll=window.scrollY;page=next;render();if(next==='editor'){const surface=root.querySelector('.editor-page');surface.tabIndex=-1;surface.focus({preventScroll:true});}window.scrollTo(0,next==='home'?homeScroll:0);turn(root,direction);}
// A card shows its buttons only while it holds focus, so the card has to take focus first.
function restoreFocus(key){const node=[...root.querySelectorAll('[data-focus-key]')].find(item=>item.dataset.focusKey===key);if(!node)return;node.closest('.card')?.querySelector('.card-head').focus({preventScroll:true});node.focus({preventScroll:true});}
function render(){hideMenu();const scroll=window.scrollY,focusKey=document.activeElement?.dataset?.focusKey;renderedView=listView();updateUI=null;if(page==='settings'||page==='connect'||page==='about')settings();else if(page==='editor')editorView();else{root.replaceChildren(toolbar(''));const main=el('main');root.append(main);home(main);}syncUpdates();window.scrollTo(0,scroll);if(focusKey)restoreFocus(focusKey);}
window.cmcpOpenAdd=()=>openEditor();
window.cmcpRenameTarget=id=>{if(page==='editor'&&editor?.id!==id){toast(data.preferences.language==='en'?'Save or cancel the current editor before renaming another device.':'请先保存或取消当前编辑，再重命名其他设备。');return false;}const target=data.targets.find(target=>target.id===id);if(!target)return false;if(page!=='editor')openEditor(target);else if(editor.category!=='general'){editor.category='general';render();}const input=root.querySelector('input[type=text]');input?.focus();input?.select();return !!input;};
window.cmcpTrayError=()=>toast('操作未完成，请检查连接状态后重试。');
if(window.CMCP_TEST)window.cmcpTest={showSettings(themeValue,language){data.preferences.theme=themeValue;data.preferences.language=language;page='settings';theme();render();},showEditor(){openEditor(data.targets[0],'web');},sshFirst(){data={...data,targets:data.targets.map((target,index)=>index?target:{...target,enabled:false,state:'stopped',loginMode:'ssh',ssh:{host:'192.0.2.9',port:22,username:'root',method:'password',keyPath:'',hasSecret:false,active:true,address:'root@192.0.2.9:22',command:'ssh -p 22 root@192.0.2.9'}})};render();},renameFirst(){return window.cmcpRenameTarget(data.targets[0].id);},showUpdate(){data.updates={state:'updating',phase:'download',received:37,total:100};renderUpdateProgress();},showUpdateFailed(){data.updates={state:'failed',code:'checksum'};renderUpdateProgress();},showAbout(){page='about';render();},showUpdateState(value){data.updates=value;syncUpdates();},resendState(){applyState(data);},relabelFirst(label){applyState({...data,targets:data.targets.map((target,index)=>index?target:{...target,label})});},refreshNow:refresh};
